#include<bits/stdc++.h>
#define int long long
using namespace std;

const int MAX_LIMIT = 5620; 
int gsm[MAX_LIMIT + 5][MAX_LIMIT + 5];

int ksm(int x, int y){
    if(x > MAX_LIMIT || y > MAX_LIMIT) {
        if(y == 0) return 1;
        if(y == 1) return x % LLONG_MAX;
        int ans = ksm(x, y / 2) % LLONG_MAX;
        ans = ans * ans % LLONG_MAX;
        if(y % 2) ans = ans * x % LLONG_MAX;
        return ans;
    }

    if(gsm[x][y] != 0) return gsm[x][y];
    if(y == 0) return gsm[x][y] = 1;
    if(y == 1) return gsm[x][y] = x % LLONG_MAX;
    
    int ans = ksm(x, y / 2) % LLONG_MAX;
    ans = ans * ans % LLONG_MAX;
    if(y % 2) ans = ans * x % LLONG_MAX;
    return gsm[x][y] = ans;
}

void func(int i) {
    for(int j = 1; j <= MAX_LIMIT; j++) {
        ksm(i, j);
    }
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    for(int i = 1; i < MAX_LIMIT; i++) {
        thread f(func, i);
        f.detach();
    }
    thread f(func, MAX_LIMIT);
    f.join();

    cout << ksm(3037000499976118, 2);

    return 0;
}
